var t=`0161-pasta-cacio-e-pepe`;var i=`world-0161`;var s=`IT`;var n=`southern-europe`;var o=4;var r=17;var l={en:`Pasta Cacio e Pepe`,ua:`Паста качо е пепе`};var p={en:`A classic dish from Italy, featuring spaghetti, pecorino romano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: спагеті, пекоріно романо. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var c=[{en:`Crush the black pepper, warm it briefly in a wide pan with a little cooking water.`,ua:`Подрібніть чорний перець і коротко прогрійте його на широкій сковороді з невеликою кількістю води.`,t:[`sauteing`,`reducing-sauce`],m:3,i:[[`ground-black-pepper`,5,`g`],[`water`,100,`ml`]]},{en:`Cook the pasta al dente, reserving at least a cup of starchy water.`,ua:`Відваріть пасту до аль денте, збережіть щонайменше чашку крохмалистої води.`,t:[`pasta-boiling`],m:10,i:[[`spaghetti`,380,`g`],[`table-salt`,9,`g`]]},{en:`Off the heat, vigorously toss pasta with finely grated Pecorino and small additions of reserved water until it emulsifies into a silky sauce.`,ua:`Поза вогнем енергійно змішайте пасту з дрібно натертим пекоріно, потроху додаючи воду з-під пасти до шовковистої емульсії.`,t:[`pasta-finishing-in-sauce`,`tossing`],m:4,i:[[`pecorino-romano`,160,`g`]]}];var u={slug:t,id:i,country:`IT`,region:n,servings:4,minutes:17,title:l,text:p,steps:c};export{s as country,u as default,i as id,r as minutes,n as region,o as servings,t as slug,c as steps,p as text,l as title};